const items = $input.all();
const item = items[0];
const form = item.json;

const category =
  form['Product Category'] ||
  form.category ||
  'Area Rug';

const focus =
  form['Focus Area'] ||
  form.focus ||
  '';

const targetAudience =
  form['🎯 Target Audience'] ||
  form['Target Audience'] ||
  form.target_audience ||
  '';

const contentGoal =
  form['🏁 Content Goal'] ||
  form['Content Goal'] ||
  form.content_goal ||
  '';

const seasonalContext =
  form['📅 Seasonal Context'] ||
  form['Seasonal Context'] ||
  form.seasonal_context ||
  '';

const primaryChannel =
  form['📱 Primary Channel'] ||
  form['Primary Channel'] ||
  form.primary_channel ||
  '';

const readBinaryFileAsText = async (binaryPropertyName) => {
  if (!item.binary?.[binaryPropertyName]) {
    return '';
  }

  const buffer = await this.helpers.getBinaryDataBuffer(
    0,
    binaryPropertyName
  );

  return buffer.toString('utf8');
};

const p2Content = await readBinaryFileAsText(
  'P2_Market_Analysis_Report'
);

const p3Content = await readBinaryFileAsText(
  'P3_Competitor_Analysis_Report'
);

const audienceResearchContent = await readBinaryFileAsText(
  'Audience_Research_Report'
);

const stripHtml = (html) => {
  return html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const p2Text = stripHtml(p2Content).slice(0, 15000);
const p3Text = stripHtml(p3Content).slice(0, 15000);
const audienceResearchText = stripHtml(audienceResearchContent).slice(0, 15000);

return [
  {
    json: {
      category,
      focus,
      target_audience: targetAudience,
      content_goal: contentGoal,
      seasonal_context: seasonalContext,
      primary_channel: primaryChannel,
      p2_content: p2Text,
      p3_content: p3Text,
      audience_research: audienceResearchText,
    },
  },
];

