const aiData = $input.first().json;
const sourceData = $('Extract Files1').first().json;

if (!aiData.output || typeof aiData.output !== 'object') {
  throw new Error('Expected structured AI output in aiData.output.');
}

return [
  {
    json: {
      content: aiData.output,
      category: sourceData.category || 'Area Rug',
      focus: sourceData.focus || '',
      target_audience: sourceData.target_audience || '',
      content_goal: sourceData.content_goal || '',
      seasonal_context: sourceData.seasonal_context || '',
      primary_channel: sourceData.primary_channel || ''
    }
  }
];
